import json

# Load the semantic index
with open('rag/documentation/_metadata/semantic_index.json', 'r') as f:
    index = json.load(f)

# Search for topics containing the exact keywords
keywords_to_find = {"sop", "geometry", "operations"}

results = {
    "sop": [],
    "geometry": [],
    "operations": []
}

for topic_name, topic_data in index.items():
    if "keywords" in topic_data:
        keywords = topic_data["keywords"]
        for keyword in keywords_to_find:
            if keyword in keywords:
                results[keyword].append(topic_name)

# Print results
for keyword in ["sop", "geometry", "operations"]:
    print(f"\n{keyword}:")
    if results[keyword]:
        for topic in sorted(results[keyword]):
            print(f"  - {topic}")
    else:
        print(f"  (no topics found)")
EOF
